mapper.select:
SELECT CASE WHEN PRA.FEASIBILITY_STATUS IS NOT NULL THEN '有效' ELSE '待处理' END AS effectStatus, pr.REQUIREMENT_ID requirementId, pr.REQUIREMENT_BASIS requirementBasis, pr.REQUIREMENT_DATE requirementDate, pr.TAR_CUSTOMER tarCustomer, pr.PRD_SCALE prdScale, pr.PRD_PERIOD prdPeriod, pr.PRD_RATE prdRate, pr.PRD_REQUIREMENT_DETIAL prdRequirementDetial, pr.REQUIREMENT_SOURCE requirementSource, PRA.FEASIBILITY_STATUS feasibilityStatus, PRA.FEASIBILITY_TYPE feasibilityType, PRA.FEASIBILITY_RESULT feasibilityResult FROM PRODUCT_REQUIREMENT pr LEFT JOIN PRODUCT_REQUIREMENT_ADD pra ON pr.REQUIREMENT_ID = pra.REQUIREMENT_ID WHERE pr.DATA_STATUS = #{STATUS_VALID,jdbcType=VARCHAR} AND PRA.REPORT_STATUS = #{REVIEW_RESULT,jdbcType=VARCHAR}
AND PRA.FEASIBILITY_STATUS IS NOT NULL
AND PRA.FEASIBILITY_STATUS IS NULL
AND PRA.FEASIBILITY_STATUS = #{feasibilityStatus}
AND PRA.FEASIBILITY_TYPE = #{feasibilityType}
AND pr.REQUIREMENT_ID = #{requirementId}
AND pr.TAR_CUSTOMER like '%' || #{tarCustomer} || '%'
